import re

def solve(env, goal):
    # Parse goal
    m = re.search(r'find (?:a |an |one |two |three )?(.+?) and put (?:them|it) in (?:a |an |the )?(\w[\w ]*?)\.?$', goal, re.I)
    if m:
        obj_name = m.group(1).strip().lower()
        target_name = m.group(2).strip().lower()
    else:
        words = goal.lower().rstrip('.').split()
        obj_name = "creditcard"
        target_name = words[-1]

    # Determine required count
    count_words = {"a": 1, "an": 1, "one": 1, "two": 2, "three": 3, "four": 4,
                   "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10}
    required = 1
    low = goal.lower()
    # Check for count word before the object
    gm = re.match(r'find (\w+)', low)
    if gm and gm.group(1) in count_words:
        required = count_words[gm.group(1)]
    else:
        for w, c in count_words.items():
            if w in ("a", "an", "one"):
                continue
            idx = low.find(w)
            if idx != -1 and idx < low.find(obj_name):
                required = c
                break

    def norm(s):
        return re.sub(r'\s+', ' ', s.strip().lower())

    def base_of(name):
        return re.sub(r'\s+\d+$', '', name).strip()

    def is_obj(item, key):
        b = base_of(item)
        return b == key or b.startswith(key) or key in b

    def parse_items(text):
        lm = re.search(r'(?:you see|you can see|you notice)\s+(.+?)(?:\.|\n|$)', text, re.I)
        if not lm:
            return []
        chunk = lm.group(1)
        parts = re.split(r',\s*|\s+and\s+', chunk)
        items = []
        for p in parts:
            p = p.strip().rstrip('.')
            if not p:
                continue
            p2 = re.sub(r'^(a|an|the)\s+', '', p, flags=re.I).strip()
            if not p2:
                continue
            if norm(p2) == "nothing":
                continue
            items.append(norm(p2))
        return items

    def parse_receptacles(text):
        lm = re.search(r'(?:you see|you can see|you notice)\s+(.+?)(?:\.|\n|$)', text, re.I)
        chunk = lm.group(1) if lm else text
        parts = re.split(r',\s*|\s+and\s*', chunk)
        out = []
        for p in parts:
            p = p.strip().rstrip('.')
            if not p:
                continue
            p2 = re.sub(r'^(a|an|the)\s+', '', p, flags=re.I).strip()
            if not p2 or norm(p2) == "nothing":
                continue
            out.append(norm(p2))
        return out

    def extract_items(text):
        res = []
        # "On the X, you see ..." / "In the X, you see ..."
        for m3 in re.finditer(r'(?:On|In|on|in) the [^,]+?, you see (.+?)(?:\.|$)', text, re.I):
            res.extend(parse_items("you see " + m3.group(1)))
        # "In it, you see ..."
        for m3 in re.finditer(r'In it, you see (.+?)(?:\.|$)', text, re.I):
            res.extend(parse_items("you see " + m3.group(1)))
        # generic "you see"
        res.extend(parse_items(text))
        seen = set()
        out = []
        for x in res:
            if x not in seen:
                seen.add(x)
                out.append(x)
        return out

    current_loc = None

    def go(loc):
        nonlocal current_loc
        if current_loc == loc:
            return env.observation
        r = env.step("go to " + loc)
        current_loc = loc
        return r

    obs = env.observation
    receptacles = parse_receptacles(obs)

    # Find target receptacle
    target_loc = None
    for r in receptacles:
        if norm(r) == norm(target_name):
            target_loc = r
            break
    if target_loc is None:
        # try fuzzy: target may be like "coffeetable 1"
        for r in receptacles:
            if norm(target_name) in norm(r):
                target_loc = r
                break
    if target_loc is None:
        target_loc = target_name

    # Search order: target first, then rest
    search_list = [target_loc] + [r for r in receptacles if r != target_loc]

    placed_count = 0
    visited = set()

    for loc in search_list:
        if placed_count >= required:
            break
        if loc in visited:
            continue
        visited.add(loc)

        r = go(loc)
        # Look
        r = env.step("look")
        items = extract_items(r)

        # If closed, open
        if re.search(r'\bclosed\b', r, re.I):
            r2 = env.step("open " + loc)
            items2 = extract_items(r2)
            # merge
            seen = set()
            tmp = []
            for x in items + items2:
                if x not in seen:
                    seen.add(x)
                    tmp.append(x)
            items = tmp
            # re-look after opening to be safe
            r3 = env.step("look")
            items3 = extract_items(r3)
            for x in items3:
                if x not in items:
                    items.append(x)

        # Take matching items
        for item in items:
            if placed_count >= required:
                break
            if is_obj(item, obj_name):
                tr = env.step("take %s from %s" % (item, loc))
                if re.search(r'pick up|you pick up|taken', tr, re.I):
                    go(target_loc)
                    dr = env.step("move %s to %s" % (item, target_loc))
                    if re.search(r'you move|move', dr, re.I):
                        placed_count += 1

    # If still not enough, do a second pass with looser matching (e.g., check inventory)
    if placed_count < required:
        # Check inventory for carried objects
        inv_r = env.step("inventory")
        inv_items = parse_items(inv_r)
        for item in inv_items:
            if placed_count >= required:
                break
            if is_obj(item, obj_name):
                go(target_loc)
                dr = env.step("move %s to %s" % (item, target_loc))
                if re.search(r'you move|move', dr, re.I):
                    placed_count += 1

    return
